   945	llvm::Optional<uint32_t> JSLexer::consumeBracedCodePoint(bool errorOnFail) {
   946	  assert(*curCharPtr_ == '{' && "braced codepoint must begin with {");
   947	  ++curCharPtr_;
   948	  const char *start = curCharPtr_;
   949	
   950	  // Set to true if we failed to get a code point that is in bounds or saw
   951	  // an invalid character.
   952	  bool failed = false;
   953	
   954	  // Loop until we hit the } or eof, max out the value, or see an invalid char.
   955	  uint32_t cp = 0;
   956	  for (; *curCharPtr_ != '}'; ++curCharPtr_) {
   957	    int ch = *curCharPtr_;
   958	    if (ch >= '0' && ch <= '9') {
   959	      ch -= '0';
   960	    } else if (ch >= 'a' && ch <= 'f') {
   961	      ch -= 'a' - 10;
   962	    } else if (ch >= 'A' && ch <= 'F') {
   963	      ch -= 'A' - 10;
   964	    } else {
   965	      // The only way this can be the end of the buffer is if this is a \0.
   966	      // Check if this is the end of the buffer, else continue so that we
   967	      // may report more errors after this braced code point.
   968	      if (curCharPtr_ == bufferEnd_) {
   969	        if (!failed && errorOnFail) {
   970	          error(
   971	              SMLoc::getFromPointer(start),
   972	              "non-terminated unicode codepoint escape");
   973	        }
   974	        return llvm::None;
   975	      }
   976	      // Invalid character, set the failed flag and continue.
   977	      if (!failed && errorOnFail) {
   978	        error(
   979	            SMLoc::getFromPointer(curCharPtr_),
   980	            "invalid character in unicode codepoint escape");
   981	      }
   982	      failed = true;
   983	      continue;
   984	    }
   985	    cp = (cp << 4) + ch;
   986	    if (cp > UNICODE_MAX_VALUE) {
   987	      // Number grew too big, set the failed flag and continue.
   988	      if (!failed && errorOnFail) {
   989	        error(
   990	            SMLoc::getFromPointer(start),
   991	            "unicode codepoint escape is too large");
   992	      }
   993	      failed = true;
   994	    }
   995	  }
   996	
   997	  assert(curCharPtr_ < bufferEnd_ && "bufferEnd_ should cause early return");
   998	
   999	  // An empty escape sequence is invalid.
  1000	  if (curCharPtr_ == start) {
  1001	    if (!failed && errorOnFail) {
  1002	      error(SMLoc::getFromPointer(start), "empty unicode codepoint escape");
  1003	    }
  1004	    failed = true;
  1005	  }
  1006	
  1007	  // Consume the final } and return.
  1008	  ++curCharPtr_;
  1009	  return failed ? llvm::None : llvm::Optional<uint32_t>{cp};
  1010	}
